def fibfib(n: int) -> int:
    # Create a dictionary to store already computed values
    memo = {0: 0, 1: 0, 2: 1}

    def helper(k: int) -> int:
        if k in memo:
            return memo[k]
        else:
            # Compute the value recursively and store it in memo
            memo[k] = helper(k - 1) + helper(k - 2) + helper(k - 3)
            return memo[k]

    return helper(n)

